input.command:
$f = "C:\Users\admin\.claude\projects\C--xp\bd54dc37-ffdb-4835-8378-42b74ce3fdef.jsonl"
$recs = Get-Content $f | ForEach-Object { $_ | ConvertFrom-Json }

# index tool_results by tool_use_id
$results = @{}
foreach ($r in $recs | Where-Object { $_.type -eq 'user' }) {
  $c = $r.message.content
  if ($c -is [array]) {
    foreach ($b in $c) {
      if ($b.type -eq 'tool_result') {
        $txt = if ($b.content -is [array]) { ($b.content | ForEach-Object { $_.text }) -join '' } else { [string]$b.content }
        $results[$b.tool_use_id] = [pscustomobject]@{ is_error = [bool]$b.is_error; bytes = $txt.Length }
      }
    }
  }
}

# walk assistant tool_use calls in order
$seq = 0
$log = New-Object System.Collections.Generic.List[object]
foreach ($r in $recs | Where-Object { $_.type -eq 'assistant' }) {
  $c = $r.message.content
  if ($c -isnot [array]) { continue }
  foreach ($b in $c) {
    if ($b.type -eq 'tool_use') {
      $seq++
      $inp = ($b.input | ConvertTo-Json -Compress -Depth 6)
      if ($inp.Length -gt 160) { $inp = $inp.Substring(0,160) + '...' }
      $res = $results[$b.id]
      $log.Add([pscustomobject]@{
        seq=$seq; ts=$r.timestamp; tool=$b.name
        status= if($res){ if($res.is_error){'ERROR'}else{'ok'} }else{'(no result)'}
        result_bytes= if($res){$res.bytes}else{0}
        input=$inp
      })
    }
  }
}

"=== TOOL EXECUTION SEQUENCE: $($log.Count) calls ==="
$log | Group-Object tool | Sort-Object Count -Descending | Select-Object Count,Name | Format-Table -Auto

"=== TOKEN USAGE (sum across assistant turns) ==="
$u = $recs | Where-Object { $_.type -eq 'assistant' } | ForEach-Object { $_.message.usage }
[pscustomobject]@{
  assistant_turns = ($recs | Where-Object {$_.type -eq 'assistant'}).Count
  input_tokens    = ($u | Measure-Object input_tokens -Sum).Sum
  output_tokens   = ($u | Measure-Object output_tokens -Sum).Sum
  cache_read      = ($u | Measure-Object cache_read_input_tokens -Sum).Sum
  cache_creation  = ($u | Measure-Object cache_creation_input_tokens -Sum).Sum
} | Format-List

# write the structured log artifact
$out = "C:\xp\WINXP-LAPTOP-2005-agent-execution-log.jsonl"
$log | ForEach-Object { $_ | ConvertTo-Json -Compress } | Set-Content $out -Encoding utf8
"wrote: $out"

